def euclid(x, y):
    while x % y != 0:
        temp = x
        x = y
        y = temp % y
    return y

n = int(input())
data = list(map(int, input().split()))
max = 0
array = data
for j in range(n):
    array = data
    array[j] = array[(j + 1) % n]
    x = data[0]
    for i in array:
        if(x > i):
            x = euclid(x, i)
        else:
            x = euclid(i, x)
        if(x > max):
            max = x
print(max)
